{"path":"events.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Gatherings — {{BUSINESS_NAME}} Events</title>
  <style>
    :root{--bg:#0f1113;--card:#0f1720;--muted:#9aa4ad;--accent:#c7f0e0;--accent-2:#7bd6ff}
    *{box-sizing:border-box}
    body{margin:0;font-family:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial;color:#e6eef2;background:linear-gradient(180deg,#050607 0%,var(--bg) 60%);line-height:1.4}
    header{position:relative;padding:28px 24px 18px;display:flex;align-items:center;justify-content:space-between}
    nav a{color:var(--muted);text-decoration:none;margin-left:18px;font-size:14px}
    .brand{font-weight:700;color:var(--accent);letter-spacing:0.6px}
    .hero{position:relative;padding:40px 24px 64px;overflow:hidden}
    .hero-inner{max-width:980px;margin:0 auto;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border-radius:12px;padding:36px;display:grid;grid-template-columns:1fr 320px;gap:20px;align-items:start}
    .title{color:#ffffff;font-size:28px;margin:0 0 6px}
    .tag{color:var(--muted);margin:0 0 18px}
    .controls{display:flex;gap:12px;align-items:center}
    select, .mixer{background:#071019;border:1px solid rgba(255,255,255,0.04);color:var(--accent);padding:10px 12px;border-radius:8px}
    .mixer{display:flex;gap:6px}
    .mixer button{padding:8px 12px;background:transparent;border-radius:8px;border:1px solid rgba(255,255,255,0.03);color:var(--muted);cursor:pointer}
    .mixer button.active{background:linear-gradient(90deg,var(--accent) 0%,var(--accent-2) 100%);color:#062024;border:1px solid rgba(0,0,0,0.15)}
    .recommend{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border-radius:10px;padding:16px;color:var(--muted)}
    .method{font-weight:700;color:#fff;margin:0 0 6px}
    .method-desc{font-size:14px;margin:0}
    .cta{display:inline-block;margin-top:12px;padding:12px 16px;border-radius:10px;background:linear-gradient(90deg,var(--accent) 0%,var(--accent-2)100%);color:#062024;text-decoration:none;font-weight:700}
    aside.card{background:#071018;border-radius:10px;padding:18px;color:var(--muted);border:1px solid rgba(255,255,255,0.02)}
    .next h4{margin:0 0 8px;color:var(--accent)}
    .next .when{font-weight:700;color:#fff}
    .events-list{margin-top:18px}
    .event-row{display:flex;justify-content:space-between;padding:10px 0;border-top:1px dashed rgba(255,255,255,0.02);color:var(--muted);font-size:14px}
    footer{padding:32px 24px;color:var(--muted);font-size:13px;text-align:center}
    .pattern-svg{position:absolute;inset:0;opacity:0.06;pointer-events:none}
    .disclaimer{font-size:12px;color:#b4bfc6;margin-top:18px}
    @media (max-width:880px){.hero-inner{grid-template-columns:1fr;}.brand{font-size:14px}nav a{display:none}}
  </style>
</head>
<body>
  <header>
    <div class="brand">{{BUSINESS_NAME}}</div>
    <nav aria-label="Main navigation">
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Fees</a>
      <a href="about.html">Practice</a>
      <a href="faq.html">Questions</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <section class="hero">
    <!-- decorative pattern -->
    <svg class="pattern-svg" viewBox="0 0 800 400" preserveAspectRatio="xMidYMid slice" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
      <defs>
        <linearGradient id="g1" x1="0" x2="1" y1="0" y2="1">
          <stop offset="0" stop-color="#7bd6ff"/>
          <stop offset="1" stop-color="#c7f0e0"/>
        </linearGradient>
        <pattern id="p1" width="60" height="60" patternUnits="userSpaceOnUse" patternTransform="rotate(15)">
          <rect width="60" height="60" fill="transparent" />
          <circle cx="30" cy="30" r="6" fill="url(#g1)" opacity="0.6" />
          <path d="M0 60 L60 0" stroke="#7bd6ff" stroke-width="0.5" opacity="0.08"/>
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill="url(#p1)" />
    </svg>

    <div class="hero-inner">
      <div>
        <h1 class="title">Gatherings in tone and hush</h1>
        <p class="tag">Small-format evenings of layered resonance in {{CITY}}, {{STATE}} — available in person and remotely.</p>

        <div class="controls">
          <label for="mood-select" style="color:var(--muted);font-size:13px">Choose how you are now</label>
          <select id="mood-select" aria-label="Mood to Method selector">
            <option value="frayed">Frayed, scattered</option>
            <option value="tired">Worn, low energy</option>
            <option value="restless">Restless, buzzing</option>
            <option value="curious">Curious, open</option>
            <option value="celebration">Celebratory, radiant</option>
            <option value="grief">Grieving, tender</option>
          </select>

          <div class="mixer" role="radiogroup" aria-label="Sound intensity">
            <button data-level="gentle" class="active">Gentle</button>
            <button data-level="medium">Medium</button>
            <button data-level="intense">Intense</button>
          </div>
        </div>

        <div class="recommend" id="recommend">
          <p class="method" id="method-title">Layered Bowls & Quiet</p>
          <p class="method-desc" id="method-desc">A slow, enveloping field of harmonic bowls with long space between tones — supports deep inhalations and soft release.</p>
          <a id="primary-cta" class="cta" href="{{PRIMARY_CTA_URL}}" data-base-label="{{PRIMARY_CTA_LABEL}}">{{PRIMARY_CTA_LABEL}}</a>
        </div>

        <p class="disclaimer">Note: Sound sessions are supportive practices, not substitutes for medical or psychiatric care. Please consult your clinician about suitability. See contraindications below.</p>
      </div>

      <aside class="card">
        <div class="next">
          <h4>Next gathering</h4>
          <div class="when">Sat • Feb 28 • 6:00 pm</div>
          <div class="where" style="margin-top:8px">Studio in {{CITY}} — exact address after booking</div>
          <div style="margin-top:12px">
            <a class="cta" href="{{PRIMARY_CTA_URL}}" id="quick-book">Reserve a spot</a>
          </div>
        </div>

        <div class="events-list">
          <h5 style="color:var(--accent);margin:12px 0 6px">Upcoming calendar</h5>
          <div class="event-row"><div>Mar 5 • Drift Circle</div><div>7:00 pm</div></div>
          <div class="event-row"><div>Mar 19 • Evening Lull</div><div>6:30 pm</div></div>
          <div class="event-row"><div>Apr 2 • Resonant Morning</div><div>9:30 am</div></div>
          <div class="event-row"><div>Apr 16 • Full-Body Sound</div><div>6:00 pm</div></div>
        </div>

        <div style="margin-top:12px;font-size:12px;color:#9fb0b9">Add an event to your calendar: <a href="mailto:?subject=Add%20Event&body=Join%20the%20next%20session%20on%20Sat%20Feb%2028%20at%206pm" style="color:var(--accent)">email reminder</a></div>
      </aside>
    </div>
  </section>

  <main style="max-width:980px;margin:20px auto;padding:0 24px">
    <section>
      <h3 style="color:var(--accent);margin:0 0 8px">How we choose the sound</h3>
      <p style="color:var(--muted);margin:0 0 12px">We mix tones, breath cues, and silence to match where you are. Use the mood selector and intensity buttons above to see the suggested format and adjust the booking label in real time.</p>

      <h4 style="color:#fff;margin-top:18px">Contraindications and safety</h4>
      <p class="disclaimer">If you have a history of seizures, recent head injury, uncontrolled psychiatric conditions, are pregnant and advised to avoid certain stimuli, or have implanted medical devices sensitive to vibration, please consult a medical professional before attending. Contact us at {{EMAIL}} or {{PHONE}} to discuss accommodations.</p>
    </section>
  </main>

  <footer>
    <div>Questions or group requests — <a href="mailto:{{EMAIL}}" style="color:var(--accent)">{{EMAIL}}</a> · {{PHONE}}</div>
  </footer>

  <script>
    (function(){
      var moodSelect = document.getElementById('mood-select');
      var mixerButtons = document.querySelectorAll('.mixer button');
      var methodTitle = document.getElementById('method-title');
      var methodDesc = document.getElementById('method-desc');
      var cta = document.getElementById('primary-cta');
      var quick = document.getElementById('quick-book');
      var baseLabel = cta.getAttribute('data-base-label') || '{{PRIMARY_CTA_LABEL}}';

      var moodMap = {
        'frayed':{method:'Soft-Field Bowls',desc:'Slow harmonics and generous silence to steady the nervous system, designed for scattered attention.'},
        'tired':{method:'Resting Resonance',desc:'Long, low tones that support quiet rest and minimal movement for deep recovery.'},
        'restless':{method:'Rhythmic Threads',desc:'Gentle pulse under higher overtones to organize energy and return focus.'},
        'curious':{method:'Explorative Layers',desc:'A varied palette of bowls, chimes, and voice to invite gentle discovery.'},
        'celebration':{method:'Bloom Session',desc:'Brighter timbres and dynamic swells for shared uplift and clear-hearted release.'},
        'grief':{method:'Tender Ground',desc:'Slower, held tones with extra pauses for careful presence and containment.'}
      };

      var intensityMap = {
        'gentle':function(m){return {suffix:'(gentle wave)',tweak:'Lower volumes, softer attack — best for deep release.'};},
        'medium':function(m){return {suffix:'(balanced)',tweak:'Moderate dynamics with more layers — supports integration.'};},
        'intense':function(m){return {suffix:'(full-bodied)',tweak:'Denser overtone presence and stronger low end — for energetic processing.'};}
      };

      function update(){
        var mood = moodSelect.value;
        var active = document.querySelector('.mixer button.active').getAttribute('data-level');
        var m = moodMap[mood] || moodMap['curious'];
        var i = intensityMap[active](m);
        methodTitle.textContent = m.method + ' ' + i.suffix;
        methodDesc.textContent = m.desc + ' ' + i.tweak;
        var newLabel = m.method + ' — ' + baseLabel;
        cta.textContent = newLabel;
        quick.textContent = 'Reserve — ' + m.method;
      }

      moodSelect.addEventListener('change', update);
      mixerButtons.forEach(function(b){
        b.addEventListener('click',function(){
          mixerButtons.forEach(function(x){x.classList.remove('active')});
          this.classList.add('active');
          update();
        });
      });

      // initialize
      update();
    })();
  </script>
</body>
</html>"} 
{"path":"private-sessions.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Private — One:One Resonance with {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071018;--panel:#0b1418;--muted:#9fb0b9;--ink:#e9f7f2;--accent:#9ef0d6}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Arial;color:var(--ink);background:radial-gradient(800px 400px at 10% 10%,rgba(125,214,255,0.04),transparent),var(--bg)}
    header{display:flex;justify-content:space-between;align-items:center;padding:22px 20px}
    .brand{font-weight:700;color:var(--accent)}
    nav a{color:var(--muted);margin-left:16px;text-decoration:none;font-size:14px}
    main{max-width:980px;margin:20px auto;padding:18px}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px}
    .panel{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:20px;border-radius:12px;border:1px solid rgba(255,255,255,0.02)}
    h1{margin:0 0 8px;color:var(--ink)}
    .lead{color:var(--muted);margin:0 0 16px}
    .options{display:flex;gap:10px;flex-wrap:wrap}
    .option{background:#07161a;padding:12px;border-radius:10px;border:1px solid rgba(255,255,255,0.03);cursor:pointer;color:var(--muted)}
    .option.active{background:linear-gradient(90deg,var(--accent) 0%,#7bd6ff 100%);color:#062024;border:1px solid rgba(0,0,0,0.12)}
    .estimate{margin-top:12px;padding:12px;border-radius:10px;background:#061019;color:var(--muted)}
    .cta{display:inline-block;margin-top:12px;padding:10px 14px;border-radius:10px;background:var(--accent);color:#042021;text-decoration:none;font-weight:700}
    .disclaimer{font-size:13px;color:#9fb0b9;margin-top:12px}
    footer{padding:26px;text-align:center;color:var(--muted)}
    @media (max-width:880px){.grid{grid-template-columns:1fr}nav a{display:none}}
  </style>
</head>
<body>
  <header>
    <div class="brand">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Fees</a>
      <a href="about.html">Practice</a>
      <a href="faq.html">Questions</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main>
    <div class="grid">
      <div>
        <section class="panel">
          <h1>Private sessions — One:One Resonance</h1>
          <p class="lead">Focused work for life transitions, performance recovery, or a personal check-in. Sessions blend tuned bowls, voice, and paced silence tailored to your nervous system.</p>

          <h4 style="color:var(--accent);margin-top:12px">Choose an approach</h4>
          <div class="options" id="approach-list">
            <div class="option active" data-role="restore">Restore — Deep rest</div>
            <div class="option" data-role="clarify">Clarify — Short tools</div>
            <div class="option" data-role="process">Process — Active release</div>
            <div class="option" data-role="embody">Embody — Movement-led</div>
          </div>

          <div style="margin-top:14px;display:flex;gap:10px;align-items:center">
            <label style="color:var(--muted);font-size:13px">Intensity</label>
            <div class="options" id="intensity-list">
              <div class="option active" data-int="gentle">Gentle</div>
              <div class="option" data-int="medium">Medium</div>
              <div class="option" data-int="intense">Intense</div>
            </div>
          </div>

          <div class="estimate" id="estimate">
            <div style="font-weight:700;color:#fff" id="estimate-title">Restore — Gentle</div>
            <div id="estimate-desc" style="margin-top:6px;color:var(--muted)">A 60-minute session with long, held tones and slow guidance. Suggested exchange: $120–$160.</div>
            <a id="book-now" class="cta" href="{{PRIMARY_CTA_URL}}" data-base="{{PRIMARY_CTA_LABEL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>

          <p class="disclaimer">Private sessions are adaptable. If you have medical concerns, epilepsy, or are pregnant, email {{EMAIL}} or call {{PHONE}} so we can support a safe plan.</p>
        </section>

        <section style="margin-top:18px;padding:18px;border-radius:12px;background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent);border:1px solid rgba(255,255,255,0.02)">
          <h4 style="margin:0 0 8px;color:var(--accent)">What to expect</h4>
          <ol style="color:var(--muted);margin:0 0 8px 18px">
            <li>Brief intake (5–10 min)</li>
            <li>Sound field (40–60 min)</li>
            <li>Grounding and practical next steps (5–10 min)</li>
          </ol>
          <p style="color:var(--muted);margin:0">Sessions may be in-studio or remote. Access needs and seating accommodations available; ask when booking.</p>
        </section>
      </div>

      <aside class="panel">
        <h4 style="color:var(--accent);margin:0 0 8px">Package windows</h4>
        <div style="color:var(--muted);font-size:14px;margin-top:8px">
          <strong style="color:#fff">Single session:</strong> Flexible timing, pay per visit.
          <div style="margin-top:8px"><strong style="color:#fff">Short series (3x):</strong> Recommended for alignment across a season.</div>
          <div style="margin-top:8px"><strong style="color:#fff">Focused intensives:</strong> 2–4 sessions for acute transition periods.</div>
        </div>

        <div style="margin-top:14px">
          <a href="mailto:{{EMAIL}}" style="color:var(--accent);text-decoration:none">Email to request a series</a>
        </div>

        <div style="margin-top:16px;color:var(--muted);font-size:13px">Sessions are offered as a sliding scale when needed. Contact us for rates if standard pricing is a barrier.</div>
      </aside>
    </div>
  </main>

  <footer>
    <div>Private scheduling and inquiries: <a href="mailto:{{EMAIL}}" style="color:var(--accent)">{{EMAIL}}</a> · {{PHONE}}</div>
  </footer>

  <script>
    (function(){
      var approaches = document.querySelectorAll('#approach-list .option');
      var intensities = document.querySelectorAll('#intensity-list .option');
      var title = document.getElementById('estimate-title');
      var desc = document.getElementById('estimate-desc');
      var book = document.getElementById('book-now');
      var base = book.getAttribute('data-base') || '{{PRIMARY_CTA_LABEL}}';

      var priceMatrix = {
        'restore':{gentle:[110,140],medium:[140,180],intense:[170,220]},
        'clarify':{gentle:[80,100],medium:[100,130],intense:[120,160]},
        'process':{gentle:[120,150],medium:[150,200],intense:[190,260]},
        'embody':{gentle:[100,130],medium:[130,170],intense:[160,210]}
      };

      function clearActive(list){list.forEach(function(x){x.classList.remove('active')});}
      function getActive(list){return Array.from(list).find(function(x){return x.classList.contains('active')});}

      function update(){
        var activeApproach = getActive(approaches).getAttribute('data-role');
        var activeIntensity = getActive(intensities).getAttribute('data-int');
        var label = getActive(approaches).textContent.trim() + ' — ' + (activeIntensity.charAt(0).toUpperCase()+activeIntensity.slice(1));
        title.textContent = label;
        var range = priceMatrix[activeApproach][activeIntensity];
        desc.textContent = 'A 60-minute private session. Suggested exchange: $' + range[0] + '–$' + range[1] + '.';
        book.textContent = label + ' · ' + base;
      }

      approaches.forEach(function(a){a.addEventListener('click',function(){clearActive(approaches);this.classList.add('active');update();})});
      intensities.forEach(function(i){i.addEventListener('click',function(){clearActive(intensities);this.classList.add('active');update();})});

      update();
    })();
  </script>
</body>
</html>"} 
{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Fees — Practical rates for sessions & circles</title>
  <style>
    :root{--bg:#071021;--card:#07161a;--muted:#9fb0b9;--accent:#9ef0d6}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;color:#eaf7f0;background:linear-gradient(180deg,#041018 0%,var(--bg) 60%)}
    header{padding:18px 20px;display:flex;justify-content:space-between;align-items:center}
    .brand{color:var(--accent);font-weight:700}
    nav a{color:var(--muted);margin-left:16px;text-decoration:none}
    main{max-width:980px;margin:18px auto;padding:18px}
    .tiers{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
    .tier{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.02)}
    .tier h3{margin:0 0 8px;color:#fff}
    .price{font-size:20px;color:var(--accent);font-weight:700}
    .adjust{margin-top:12px;padding:12px;border-radius:10px;background:#061017;color:var(--muted)}
    .mixer{margin-top:10px;display:flex;gap:8px}
    .mixer button{padding:8px 12px;border-radius:8px;border:1px solid rgba(255,255,255,0.03);background:transparent;color:var(--muted);cursor:pointer}
    .mixer button.active{background:var(--accent);color:#042021}
    .cta{display:inline-block;margin-top:12px;padding:10px 14px;border-radius:10px;background:var(--accent);color:#042021;text-decoration:none;font-weight:700}
    .note{margin-top:12px;color:var(--muted);font-size:13px}
    footer{padding:22px;text-align:center;color:var(--muted)}
    @media (max-width:920px){.tiers{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div class="brand">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Fees</a>
      <a href="about.html">Practice</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main>
    <h1 style="margin:0 0 8px">Fees and suggested exchanges</h1>
    <p class="note">We present rates as suggested exchanges with a sliding option for accessibility. Contact {{EMAIL}} for scholarship availability.</p>

    <div class="tiers">
      <div class="tier">
        <h3>Circles — Shared Field</h3>
        <div class="price" id="price-circles">$20</div>
        <p style="color:var(--muted);margin:8px 0">Per person, evening gatherings with a quiet start and shared close.</p>
        <div class="adjust">
          <div style="color:var(--muted)">Intensity</div>
          <div class="mixer" data-target="circles">
            <button data-level="gentle" class="active">Gentle</button>
            <button data-level="medium">Medium</button>
            <button data-level="intense">Intense</button>
          </div>
        </div>
        <a id="cta-circles" class="cta" href="{{PRIMARY_CTA_URL}}" data-base="{{PRIMARY_CTA_LABEL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>

      <div class="tier">
        <h3>One:One Resonance</h3>
        <div class="price" id="price-private">$140</div>
        <p style="color:var(--muted);margin:8px 0">A focused private session for recovery or real-world transitions.</p>
        <div class="adjust">
          <div style="color:var(--muted)">Intensity</div>
          <div class="mixer" data-target="private">
            <button data-level="gentle" class="active">Gentle</button>
            <button data-level="medium">Medium</button>
            <button data-level="intense">Intense</button>
          </div>
        </div>
        <a id="cta-private" class="cta" href="{{PRIMARY_CTA_URL}}" data-base="{{PRIMARY_CTA_LABEL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>

      <div class="tier">
        <h3>Short Track Series</h3>
        <div class="price" id="price-series">$320</div>
        <p style="color:var(--muted);margin:8px 0">Three-session clusters tuned to a single aim — alignment, recovery, or clarity.</p>
        <div class="adjust">
          <div style="color:var(--muted)">Intensity</div>
          <div class="mixer" data-target="series">
            <button data-level="gentle" class="active">Gentle</button>
            <button data-level="medium">Medium</button>
            <button data-level="intense">Intense</button>
          </div>
        </div>
        <a id="cta-series" class="cta" href="{{PRIMARY_CTA_URL}}" data-base="{{PRIMARY_CTA_LABEL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </div>

