  </footer>

  <script>
    (function(){
      var matrices = {
        'circles':{gentle:18,medium:22,intense:26},
        'private':{gentle:110,medium:140,intense:180},
        'series':{gentle:280,medium:320,intense:380}
      };
      var mixers = document.querySelectorAll('.mixer');

      mixers.forEach(function(m){
        var target = m.getAttribute('data-target');
        m.addEventListener('click',function(e){
          var btn = e.target.closest('button');
          if(!btn) return;
          var level = btn.getAttribute('data-level');
          // toggle active
          Array.from(m.querySelectorAll('button')).forEach(function(x){x.classList.remove('active')});
          btn.classList.add('active');
          // update price
          var priceEl = document.getElementById('price-' + target);
          var newPrice = matrices[target][level];
          if(priceEl) priceEl.textContent = '$' + newPrice;
          // update cta label
          var cta = document.getElementById('cta-' + target);
          if(cta){
            var base = cta.getAttribute('data-base') || '{{PRIMARY_CTA_LABEL}}';
            cta.textContent = (target === 'private' ? 'Book private' : (target === 'circles' ? 'Join circle' : 'Start series')) + ' — ' + level.charAt(0).toUpperCase()+level.slice(1) + ' · ' + base;
          }
        });
      });

      // initialize labels for all mixers (simulate click on active)
      document.querySelectorAll('.mixer').forEach(function(m){
        var active = m.querySelector('button.active');
        if(active) active.click();
      });
    })();
  </script>
